// U3 New-Contact Intent Classifier - strict envelope entry guard. Hard-fail on contract violation.
const input = $input.first().json;
const e164 = /^\+?[1-9]\d{6,14}$/;
if (typeof input.phoneNumber !== 'string' || !e164.test(input.phoneNumber)) {
  throw new Error('U3 entry-guard: phoneNumber missing or not E.164: ' + JSON.stringify(input.phoneNumber));
}
if (typeof input.text !== 'string' || input.text.trim() === '') {
  throw new Error('U3 entry-guard: text missing or empty');
}
if (input.stage !== 'new' && input.stage !== 'pre_form') {
  throw new Error('U3 entry-guard: stage must be "new" or "pre_form": ' + JSON.stringify(input.stage));
}
const cid = input.consultChannelId;
if (cid !== undefined && cid !== null && cid !== '' && !/^[CDG][A-Z0-9]+$/.test(cid)) {
  throw new Error('U3 entry-guard: consultChannelId not a valid Slack channel id: ' + JSON.stringify(cid));
}
return [{ json: {
  phoneNumber: input.phoneNumber,
  text: input.text,
  stage: input.stage,
  consultChannelId: (cid === undefined || cid === '' ? null : cid)
} }];

const geminiResp = $input.first().json;
const VALID = ['greeting','wants_consultation','service_related_question','HELP','unrelated','garbage','stop_intent','malicious','abusive','inappropriate'];
let bucket = 'unrelated';
let confidence = 0;
try {
  let raw = (geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();
  raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const parsed = JSON.parse(raw);
  if (parsed && VALID.includes(parsed.bucket) && typeof parsed.confidence === 'number') {
    bucket = parsed.bucket;
    confidence = parsed.confidence;
  }
} catch (e) { /* malformed -> safe fail-open default unrelated/0 (caller treats <0.5 as unrelated) */ }
return [{ json: { bucket, confidence } }];

